    delim_col = delim_row = -1
    delim_type = -1  # 0=vertical, 1=horizontal

    # Check horizontal delimiter first
    for r in range(h):
        if all(grid[r][c] != bg and grid[r][c] == grid[r][0] for c in range(w)):
            v = grid[r][0]
            if v != bg:
                delim_row = r
                delim_type = 1
                break

    # Check vertical if not found
    if delim_type == -1:
        for c in range(w):
            v = grid[0][c]
            if v != bg and all(grid[r][c] == v for r in range(h)):
                delim_col = c
                delim_type = 0
                break

    if delim_type == -1:
        return [row[:] for row in grid]

    if delim_type == 1:  # Horizontal
        # Find object rows
        min_r, max_r = h, -1
